"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4059],{6840:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[{"name":"ClientStateFields","desc":"Every field on the [ClientState] singleton.\\n\\n`version` is read once at require time from the `Version` value under\\nReplicatedStorage \u2014 it is a plain string, not a State, and never changes.\\n`currentFTUEStep` is likewise a plain value rather than a State, so it\\ncannot be subscribed to; read it directly.","fields":[{"name":"version","lua_type":"string","desc":"Build version, copied from ReplicatedStorage.Version at require time"},{"name":"ready","lua_type":"State<boolean>","desc":"False until the client has finished booting and dispatched `READY`"},{"name":"playerData","lua_type":"State<ProfileTypes.ProfileData>","desc":"Mirror of the Profile Replica. Seeded from `DataTemplate` so it is never nil"},{"name":"coins","lua_type":"State<number>","desc":"`playerData.stats.coins`, projected so coin-only consumers don\'t wake on every profile change"},{"name":"xp","lua_type":"State<number>","desc":"`playerData.stats.xp`, projected the same way"},{"name":"activeBlurs","lua_type":"State<{ string }>","desc":"Ids of the UI layers currently requesting a background blur; blur is on while non-empty"},{"name":"hotbarSlots","lua_type":"State<{ [number]: InventoryData.HotbarSlot }>","desc":"Hotbar contents keyed by slot index"},{"name":"hotbarVisible","lua_type":"State<boolean>","desc":"False in the lobby; round/game code sets true to show the hotbar"},{"name":"currentlySelectedHotbarItemRecord","lua_type":"State<{ itemRecord: Types.ItemRecord? }>","desc":"The equipped hotbar item, wrapped so \\"nothing equipped\\" is a table with a nil field rather than a nil state"},{"name":"friendBoost","lua_type":"State<number>","desc":"Multiplier earned from friends in the server, per `BoostData.getBoostPerFriend`"},{"name":"inVehicle","lua_type":"State<boolean>","desc":"True while the local player is driving or riding"},{"name":"currentFTUEStep","lua_type":"number?","desc":"Index of the active first-time-user-experience step, or nil when the FTUE is not running"}],"source":{"line":67,"path":"src/Client/ClientState.luau"}}],"name":"ClientState","desc":"The client\'s single shared store. Nearly every component and controller\\nreads from it, so treat it as public API: renaming or removing a field\\nbreaks callers spread across the whole client tree.\\n\\nEach field (other than `version` and `currentFTUEStep`) is a `State`\\nobject \u2014 read with `:Get()`, write with `:Set()`, subscribe with\\n`.Changed`. React components generally wrap those subscriptions in an\\neffect and mirror the value into `useState`.\\n\\n### Who writes what\\n\\nWriters are deliberately few; if a component is calling `:Set()` on\\nanything here, it is probably a layering mistake.\\n\\n* `playerData` \u2014 [DataController], from the Profile Replica.\\n* `coins`, `xp` \u2014 [StatsController], projected out of `playerData.stats`.\\n* `friendBoost` \u2014 [SocialController], from the friends-in-server poll.\\n* `ready` \u2014 `Entry.client.luau`, right after it dispatches `READY`.\\n* `hotbarSlots`, `currentlySelectedHotbarItemRecord` \u2014 the hotbar feature.\\n* `activeBlurs`, `inVehicle`, `currentFTUEStep` \u2014 their respective features.\\n\\nSee [ClientStateFields] for the individual fields.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","realm":["Client"],"source":{"line":31,"path":"src/Client/ClientState.luau"}}')}}]);